-- Apply over the classic tables.
do
    local DB, F = ns.DB, ns.ForeverLoot
    if not (DB and DB.items and DB.loot) then return end
    for id, name in pairs(F.names) do
        if not DB.items[id] then
            local recipe = name:match("^Pattern:") or name:match("^Plans:") or name:match("^Recipe:") or name:match("^Formula:")
                or name:match("^Schematic:") or name:match("^Blueprint:") or name:match("^Design:") or name:match("^Manual:")
            DB.items[id] = { name, recipe and 2 or 3, 0, 0, 0, recipe and 9 or 0, 0, -1 }
        end
    end
    for id, name in pairs(F.npcs) do DB.npcs[id] = DB.npcs[id] or name end
    for npc, list in pairs(F.loot) do
        local old, chance, out = DB.loot[npc] or {}, {}, {}
        for i = 1, #old, 2 do chance[old[i]] = old[i + 1] end
        if F.mode[list[1]] == "merge" then
            for i = 1, #old do out[i] = old[i] end
        else
            -- keep the boss's quest items (item class 12) from the classic list
            for i = 1, #old, 2 do
                local it = DB.items[old[i]]
                if it and it[6] == 12 then out[#out + 1] = old[i]; out[#out + 1] = old[i + 1] end
            end
        end
        for i = 2, #list do
            local id = list[i]
            if not (F.mode[list[1]] == "merge" and chance[id] ~= nil) then
                out[#out + 1] = id; out[#out + 1] = chance[id] or false
            end
        end
        DB.loot[npc] = out
    end
    for npc, list in pairs(F.recipes) do
        local t = DB.loot[npc] or {}
        local have = {}
        for i = 1, #t, 2 do have[t[i]] = true end
        for _, id in ipairs(list) do
            if not have[id] then t[#t + 1] = id; t[#t + 1] = false end
        end
        DB.loot[npc] = t
    end
    DB.trash = DB.trash or {}
    for mapID, list in pairs(F.trash) do
        local t = DB.trash[mapID] or {}
        local have = {}
        for i = 1, #t, 3 do have[t[i]] = true end
        for i = 1, #list, 2 do
            if not have[list[i]] then t[#t + 1] = list[i]; t[#t + 1] = false; t[#t + 1] = list[i + 1] end
        end
        DB.trash[mapID] = t
    end
end
